from __future__ import annotations

import asyncio
import sys
from pathlib import Path
from typing import TYPE_CHECKING

import ds.ai
import pytest
from pydantic_ai.models.function import AgentInfo, DeltaToolCall, DeltaToolCalls, FunctionModel

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

from ui import agents, app_guide, session  # noqa: E402
from ui.commands import SLASH  # noqa: E402
from ui.shortcuts import Shortcut  # noqa: E402

if TYPE_CHECKING:
    from collections.abc import AsyncIterator

    from pydantic_ai.messages import ModelMessage

# the guide is loaded whole, on top of every later request of the chat: keep it short
MAX_GUIDE_LINES = 160


def test_the_guide_is_short_and_has_no_notes_for_editors() -> None:
    assert len(app_guide.GUIDE.read_text(encoding="utf-8").splitlines()) <= MAX_GUIDE_LINES
    text = app_guide.guide_text()
    assert text.startswith("# Using delulu-smash")
    assert "<!--" not in text
    assert "AUTO-GENERATED" not in text


@pytest.mark.parametrize("name", list(SLASH))
def test_every_slash_command_has_words_in_the_guide(name: str) -> None:
    # a new slash command: say what it is for in services/ui/guide.md
    assert f"`/{name}`" in app_guide.guide_text() or f"\n/{name}" in app_guide.guide_text()


def test_the_lists_come_from_the_code() -> None:
    text = app_guide.instructions()
    for name, command in SLASH.items():
        assert f"/{name}" in app_guide.slash_table()
        assert command.title in text
    for shortcut in Shortcut:
        assert shortcut.value.what in text
    assert "/script <[name] | list | delete <id>>" in text
    assert "never\n  invent" in text  # the rules come first


def test_a_missing_guide_still_gives_the_lists(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    monkeypatch.setattr(app_guide, "GUIDE", tmp_path / "gone.md")
    text = app_guide.instructions()
    assert app_guide.MISSING in text
    assert "/clear-chat" in text
    assert Shortcut.PALETTE.keys in text


def test_the_guide_is_read_again_on_every_load(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    guide = tmp_path / "guide.md"
    monkeypatch.setattr(app_guide, "GUIDE", guide)
    guide.write_text("<!-- a note -->\n# One", encoding="utf-8")
    assert "# One" in app_guide.instructions()
    guide.write_text("# Two", encoding="utf-8")
    assert "# Two" in app_guide.instructions()


def test_the_agents_tab_lists_it_as_added_by_the_app() -> None:
    chat = agents.AGENTS[0]
    guide = next(cap for cap in chat.capabilities if cap.name == "app_guide")
    assert guide.loads == agents.DEFERRED
    assert not guide.tools
    assert "# Using delulu-smash" in guide.instructions
    assert "app_guide" in chat.loading[-1]["value"]
    # the agent in pkgs/ds/ai is not changed: evals and the CLI don't get the guide
    own = [getattr(cap, "id", None) for cap in ds.ai.agent.root_capability.capabilities]
    assert "app_guide" not in own


def test_a_chat_run_offers_the_guide_and_the_model_can_load_it() -> None:
    requests: list[str] = []

    async def respond(messages: list[ModelMessage], info: AgentInfo) -> AsyncIterator[str | DeltaToolCalls]:
        # the newest message: a loaded capability's instructions are one of its parts
        requests.append("\n".join(str(getattr(part, "content", "")) for part in messages[-1].parts))
        if len(requests) == 1:
            assert "- app_guide: How to use this app" in info.instructions
            assert "# Using delulu-smash" not in info.instructions  # not before it is loaded
            yield {0: DeltaToolCall(name=agents.LOAD_TOOL, json_args='{"id": "app_guide"}', tool_call_id="load")}
        else:
            yield "Type /script after a browser run."

    async def on_delta(_: str) -> None:
        return None

    chat = session.Session()
    with ds.ai.agent.override(model=FunctionModel(stream_function=respond)):
        result = asyncio.run(chat.ask("show me how to use the script slash command", on_delta))
    assert not result.error
    assert result.text == "Type /script after a browser run."
    # the second request carries the guide and the live lists
    assert "# Using delulu-smash" in requests[1]
    assert "/script <[name] | list | delete <id>>" in requests[1]
    assert agents.activity(chat.ai_history)
